function showModal(title,body,button='GOT IT'){ $('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalOkay').innerHTML=`${button} <span>→</span>`;$('#modal').classList.add('open') }
function closeModal(){ $('#modal').classList.remove('open') }
function newGame(){state={home:0,away:0,quarter:1,clock:900,ball:25,down:1,toGo:10,possession:'home',drives:1,yards:0,turnovers:0,selected:'run',gameOver:false,playClock:25,feed:[]};addFeed('Kickoff! You’re starting at your own 25.');$('#resultBanner').className='result-banner';$('#resultBanner').textContent='';render();closeModal()}
$('#playOptions').addEventListener('click',e=>{let b=e.target.closest('.play-option');if(!b||state.gameOver||state.possession!=='home')return;state.selected=b.dataset.play;render()});$('#snapBtn').addEventListener('click',resolvePlay);
$('#specialBtn').addEventListener('click',()=>{if(state.down!==4||state.possession!=='home'||state.gameOver)return;let distance=100-state.ball;if(distance<=37){let made=Math.random()<.78;advanceClock(7);if(made){$('#resultBanner').textContent='FIELD GOAL IS GOOD!';score('home',3,'Field goal is good! Metro Bolts add three.')}else{$('#resultBanner').textContent='Field goal no good.';addFeed('Field goal attempt is wide. Iron City takes over.');finishDrive('away',true)}render();return}showModal('4th down decision',`<p>You’re facing <b>${state.toGo} yards</b> on 4th down. Choose how to play it:</p><div class="decision-actions"><button class="decision-btn" data-choice="punt"><b>📣 Punt it</b><small>Flip the field and trust your defense.</small></button><button class="decision-btn" data-choice="go"><b>💪 Go for it</b><small>Keep the drive alive. Fail and they take over.</small></button></div><p class="modal-note">Field goals are available automatically when you’re in range.</p>`,'CANCEL');$$('.decision-btn').forEach(b=>b.onclick=()=>{let choice=b.dataset.choice;closeModal();advanceClock(8);if(choice==='punt'){addFeed('You punt. Iron City starts deep in its territory.');state.possession='away';state.ball=82;state.down=1;state.toGo=10;state.drives++;render();setTimeout(aiDrive,450)}else{let needed=state.toGo;let gained=Math.floor(Math.random()*9)+1;if(gained>=needed){addFeed(`You go for it and convert! ${gained} yards.`);state.down=1;state.toGo=10;state.ball+=gained;render()}else{addFeed('Stuffed! Turnover on downs. Iron City takes over.','turnover');finishDrive('away',true)}}});$('#modalOkay').textContent='CANCEL'});
$('#newGameBtn').addEventListener('click',()=>showModal('Start a new game?','<p>Your current game will be reset. Ready to take the field again?</p><div class="decision-actions"><button class="decision-btn" id="confirmNew"><b>🏈 New game</b><small>Kick off a fresh matchup.</small></button><button class="decision-btn" id="keepGame"><b>↩ Keep playing</b><small>Stay in this game.</small></button></div>','CLOSE'));
$('#modal').addEventListener('click',e=>{if(e.target.id==='confirmNew')newGame();if(e.target.id==='keepGame'||e.target.id==='modalClose')closeModal()});$('#modalClose').addEventListener('click',closeModal);$('#modalOkay').addEventListener('click',()=>{if(state.gameOver){newGame()}else closeModal()});$('#helpBtn').addEventListener('click',()=>showModal('How to play','<p><b>Move the ball downfield:</b> choose a run or pass, then snap the ball. A big roll adds extra yards.</p><p><b>Earn a first down:</b> gain the yards shown before you run out of four downs. Score a touchdown for 7 or kick a field goal for 3.</p><p><b>Make the call:</b> run plays are reliable, quick passes balance risk and reward, and deep shots can change a game—or get picked off.</p><p><b>On 4th down:</b> punt, kick a field goal when close, or go for it. The AI plays its own drives automatically. Highest score after four quarters wins.</p>','GOT IT'));
addFeed('Kickoff! You’re starting at your own 25.');render();
